from fastapi import FastAPI, Header, Depends
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class HeaderModel(BaseModel):
    my_header: str = Header(convert_underscores=True)

@app.get("/headers")
def get_headers(headers: HeaderModel = Depends()):
    return headers

client = TestClient(app)

def test_convert_underscores_true():
    # Should accept hyphenated
    resp = client.get("/headers", headers={"my-header": "value1"})
    assert resp.status_code == 200
    assert resp.json() == {"my_header": "value1"}

    # Should reject underscore (or at least not use it)
    # If it's rejected, it might be a 422 if required.
    # In HeaderModel, my_header is required.
    resp = client.get("/headers", headers={"my_header": "value2"})
    assert resp.status_code == 422
    print("Underscore rejected as expected")

def test_convert_underscores_false():
    # We need a different route for this
    pass

app2 = FastAPI()
class HeaderModelFalse(BaseModel):
